"""The owner's own project: weather-app on EKS. Source: the project's handbook.
The site is public, so this chapter teaches the design and leaves out every identifier
(account, domain, addresses, instance and volume ids, user names, credentials)."""
from _h import *


def FIVE(name, built, why, rejected, cost, prod):
    """One component through the five defense questions: a heading and five numbered answers."""
    return [H(name),
            STEPS("**מה בנית:** " + built, "**למה כך:** " + why, "**מה נדחה:** " + rejected,
                  "**מה המחיר:** " + cost, "**מה היית משנה:** " + prod)]


